import cdp,time,subprocess
exp=subprocess.check_output(['node','-e','''const vm=require("vm"),fs=require("fs");const c={window:{},localStorage:{getItem(){return null},setItem(){}}};vm.createContext(c);vm.runInContext(fs.readFileSync("/downloads/shots/src/platform/js/data.js","utf8")+";globalThis.__E=INITIAL_EXAMS",c);const q=c.__E[0].questions;console.log(Math.round(q.filter(x=>x.correctAnswer===0).length/q.length*100))''']).decode().strip()
p,ws=cdp.start(9353); c=cdp.C(ws); c.size(1280,900)
B='http://127.0.0.1:3199/'; ok=[]
def chk(n,v):
    ok.append(bool(v)); print('PASS' if v else 'FAIL',n)
c.go(B+'login.html',3)
c.js("""(async()=>{const h={'Content-Type':'application/json'};await fetch('/api/register',{method:'POST',headers:h,body:JSON.stringify({name:'Exam Student',email:'es@t.com',password:'Student-Pass-123'})});await fetch('/api/login',{method:'POST',headers:h,body:JSON.stringify({email:'es@t.com',password:'Student-Pass-123'})});localStorage.setItem('esentry_role','student');localStorage.setItem('esentry_user_role','student');localStorage.setItem('isLoggedIn','true');localStorage.setItem('active_user','es@t.com');return 1})()""")
c.go(B+'exams.html?id=exam-1',4)
chk('exam page in server mode', c.js('window.ES_SERVER_EXAMS')==True)
chk('30 questions loaded from API', c.js('currentExam&&currentExam.questions.length')==30)
chk('no answer key in the exam object the page uses', c.js('currentExam&&!currentExam.questions.some(q=>"correctAnswer" in q)')==True)
chk('served js/data.js and browser storage hold no answer key', c.js("fetch('/js/data.js').then(r=>r.text()).then(t=>!/correctAnswer/.test(t)&&!/\"explanation\"/.test(t)&&!/correctAnswer/.test(localStorage.getItem('esentry_exams')||''))")==True)
c.js('currentExam.questions.forEach(q=>userAnswers[q.id]=0)')
c.js('submitExam()'); time.sleep(2)
chk('server score shown (%s expected)'%exp, c.js("document.getElementById('result-score-percent').textContent")==exp+'%')
n=c.js("document.querySelectorAll('#exam-questions-review > div').length"); chk('30 review cards',n==30)
chk('explanations only for correct answers', c.js("document.querySelectorAll('#exam-questions-review .text-emerald-400').length")==round(int(exp)*30/100))
c.go(B+'exams.html',3)
chk('list marks exam completed', c.js("document.getElementById('available-exams-grid').innerText.includes('تم الاجتياز')"))
c.go(B+'exams.html?id=exam-1',3)
chk('retake blocked', c.js("document.getElementById('active-exam-view').classList.contains('hidden')"))
print({'passed':sum(ok),'total':len(ok)})
p.terminate()
